svg.script:

(function() {
  // Namespace isolated script
  const svg = document.getElementById('a12p7h-svg-root');
  if (!svg) return;

  // Element References
  const modeBtn1 = document.getElementById('a12p7h-mode-btn-1');
  const modeBtn2 = document.getElementById('a12p7h-mode-btn-2');
  const modeBtn3 = document.getElementById('a12p7h-mode-btn-3');

  const layerMembrane = document.getElementById('a12p7h-layer-membrane');
  const layerMuscle = document.getElementById('a12p7h-layer-muscle');
  const layerNav = document.getElementById('a12p7h-layer-nav');
  const zoneDanger = document.getElementById('a12p7h-zone-danger');
  const zoneSafe = document.getElementById('a12p7h-zone-safe');
  const simLayer = document.getElementById('a12p7h-sim-layer');

  const statusDot = document.getElementById('a12p7h-status-dot');
  const statusTitle = document.getElementById('a12p7h-status-title');
  const statusSub = document.getElementById('a12p7h-status-sub');

  const descTitle = document.getElementById('a12p7h-desc-title');
  const descBody1 = document.getElementById('a12p7h-desc-body1');
  const descBody2 = document.getElementById('a12p7h-desc-body2');
  const descBody3 = document.getElementById('a12p7h-desc-body3');
  const descBody4 = document.getElementById('a12p7h-desc-body4');
  const descHighlightText1 = document.getElementById('a12p7h-desc-highlight-text1');
  const descHighlightText2 = document.getElementById('a12p7h-desc-highlight-text2');

  const tooltip = document.getElementById('a12p7h-tooltip');
  const tooltipTitle = document.getElementById('a12p7h-tooltip-title');
  const tooltipSub = document.getElementById('a12p7h-tooltip-sub');
  const tooltipBg = document.getElementById('a12p7h-tooltip-bg');

  // Helper: Set Button Active State
  function setMode(mode) {
    [modeBtn1, modeBtn2, modeBtn3].forEach((btn, idx) => {
      if (idx === mode - 1) {
        btn.classList.add('a12p7h-btn-active');
      } else {
        btn.classList.remove('a12p7h-btn-active');
      }
    });

    if (mode === 1) {
      // Visão Geral
      simLayer.classList.remove('a12p7h-layer-visible');
      simLayer.classList.add('a12p7h-layer-hidden');
      layerMuscle.classList.remove('a12p7h-layer-visible');
      layerMuscle.classList.add('a12p7h-layer-hidden');

      updatePanel(
        '#22c55e',
        'ESTADO: Visão Geral Anatômica',
        'Toque nos componentes da imagem para detalhar',
        '1. O Conceito: Janela Grande × Fresta Pequena',
        '• O Forame Obturatório é delimitado pelo Púbis e Ísquio.',
        '• A Membrana Obturatória oclui ~95% da janela óssea.',
        '• O Feixe NAV (Nervo, Artéria, Veia) passa no Canal Súpero-Lateral.',
        '• A região Ínfero-Lateral é livre de vasos e nervos importantes.',
        'REGRA DE RESIDÊNCIA:',
        'A agulha de TOT entra pela zona ÍNFERO-LATERAL para não lesar o NAV!'
      );
    } else if (mode === 2) {
      // Simulador TOT / Punção
      simLayer.classList.remove('a12p7h-layer-hidden');
      simLayer.classList.add('a12p7h-layer-visible');
      layerMuscle.classList.remove('a12p7h-layer-visible');
      layerMuscle.classList.add('a12p7h-layer-hidden');

      updatePanel(
        '#22c55e',
        'SIMULADOR: Passagem de Agulha de TOT',
        'Trajeto seguro vs. Trajeto de risco de lesão vasculonervosa',
        '2. Correlação Cirúrgica: Slings Transobturatórios (TOT)',
        '• Trajeto Seguro (Verde): Perfura membrana na zona ínfero-lateral.',
        '• Distância do NAV: A agulha passa a > 2cm de distância do canal.',
        '• Erro de Trajeto (Vermelho): Direcionamento superior arrisca o NAV.',
        '• Lesão de Nervo Obturatório: Causa paresia dos adutores da coxa.',
        'ALERTA CIRÚRGICO:',
        'Mantenha a ponta da agulha junto ao ramo inferior do púbis!'
      );
    } else if (mode === 3) {
      // Parede Pélvica / Músculo
      simLayer.classList.remove('a12p7h-layer-visible');
      simLayer.classList.add('a12p7h-layer-hidden');
      layerMuscle.classList.remove('a12p7h-layer-hidden');
      layerMuscle.classList.add('a12p7h-layer-visible');

      updatePanel(
        '#f97316',
        'PAREDE PELVICA: Músculo Obturador Interno',
        'Relação anatômica entre parede muscular e o assoalho pélvico',
        '3. Parede Lateral da Pelve menor',
        '• Músculo Obturador Interno forra a face interna da membrana.',
        '• Suas fibras emergem pelo Pequeno Forame Isquiático.',
        '• Ele faz parte da PAREDE lateral pélvica, NÃO do assoalho.',
        '• Fascia do obturador interno dá origem ao Arco Tendíneo do Elevador.',
        'DISTRATOR CLÁSICO:',
        'Não confunda M. Obturador Interno (Parede) com Levator Ani (Chão)!'
      );
    }
  }

  function updatePanel(dotColor, statusTitleText, statusSubText, titleText, b1, b2, b3, b4, h1, h2) {
    if (statusDot) statusDot.setAttribute('fill', dotColor);
    if (statusTitle) statusTitle.textContent = statusTitleText;
    if (statusSub) statusSub.textContent = statusSubText;
    if (descTitle) descTitle.textContent = titleText;
    if (descBody1) descBody1.textContent = b1;
    if (descBody2) descBody2.textContent = b2;
    if (descBody3) descBody3.textContent = b3;
    if (descBody4) descBody4.textContent = b4;
    if (descHighlightText1) descHighlightText1.textContent = h1;
    if (descHighlightText2) descHighlightText2.textContent = h2;
  }

  // Mode Click Event Listeners
  if (modeBtn1) modeBtn1.addEventListener('click', () => setMode(1));
  if (modeBtn2) modeBtn2.addEventListener('click', () => setMode(2));
  if (modeBtn3) modeBtn3.addEventListener('click', () => setMode(3));

  // Tooltip Follow Engine
  function showTooltip(title, sub, evt) {
    if (!tooltip) return;
    tooltipTitle.textContent = title;
    tooltipSub.textContent = sub;

    // Measure text for dynamic bg width
    const width = Math.max(title.length, sub.length) * 7.5 + 24;
    tooltipBg.setAttribute('width', Math.max(160, width));

    tooltip.setAttribute('opacity', '1');
    moveTooltip(evt);
  }

  function moveTooltip(evt) {
    if (!tooltip || !svg.getScreenCTM) return;
    const pt = svg.createSVGPoint();
    pt.x = evt.clientX;
    pt.y = evt.clientY;
    const svgP = pt.matrixTransform(svg.getScreenCTM().inverse());

    let tx = svgP.x + 15;
    let ty = svgP.y + 15;
    if (tx > 800) tx = svgP.x - 190;
    if (ty > 600) ty = svgP.y - 50;

    tooltip.setAttribute('transform', `translate(${tx}, ${ty})`);
  }

  function hideTooltip() {
    if (tooltip) tooltip.setAttribute('opacity', '0');
  }

  // Hotspot Attachments
  const hotspots = [
    {
      el: zoneDanger,
      title: 'Canal Obturatório (Súpero-Lateral)',
      sub: 'Zona de Risco - Feixe NAV (Nervo, Artéria, Veia)',
      onClick: () => {
        updatePanel(
          '#ef4444',
          'ALERTA: Feixe Vasculonervoso Obturatório',
          'Localização súpero-lateral no forame obturatório',
          'Canal Obturatório e Feixe NAV',
          '• Nervo Obturatório (L2-L4): Motor para adutores da coxa.',
          '• Artéria Obturatória: Ramo ilíaco interno (ou Corona Mortis).',
          '• Veia Obturatória: Drenagem venosa pélvica.',
          '• Risco em Cirurgias: Perfuração inadvertida no canal.',
          'PERIGO DE LESÃO:',
          'Nunca direcione agulhas ou trocartes ao canto súpero-lateral!'
        );
      }
    },
    {
      el: zoneSafe,
      title: 'Território Seguro (Ínfero-Lateral)',
      sub: 'Zona de Punção e Ancoragem de Sling TOT',
      onClick: () => {
        updatePanel(
          '#22c55e',
          'ZONA SEGURA: Região Ínfero-Lateral',
          'Território sem estruturas vasculonervosas nobres',
          'Território Seguro da Membrana',
          '• Área fibrosa ampla livre de nervos e vasos de grande calibre.',
          '• Ideal para passagem de agulhas cirúrgicas (Sling TOT).',
          '• Ancoragem de telas de prolapso pélvico anterior.',
          '• Trajeto seguro rente ao ramo inferior do púbis.',
          'ZONA DE ELEIÇÃO:',
          'Ponto de entrada do trocarte na cirurgia de incontinência!'
        );
      }
    },
    {
      el: layerMembrane,
      title: 'Membrana Obturatória',
      sub: 'Oclui ~95% da área do forame obturatório',
      onClick: () => {
        updatePanel(
          '#881337',
          'ESTRUTURA: Membrana Obturatória',
          'Lâmina aponeurótica resistente que cobre a janela óssea',
          'Membrana Obturatória (Corpo Fibroso)',
          '• Conecta as margens ósseas do púbis e ísquio.',
          '• Transforma o grande forame em uma fresta pequena (canal).',
          '• Serve de origem para os músculos obturadores interno e externo.',
          '• Fornece suporte mecânico à parede anterolateral da pelve.',
          'CONCEITO CHAVE:',
          'Transforma a janela óssea grande em um pequeno canal vascular!'
        );
      }
    },
    {
      el: layerNav,
      title: 'Feixe NAV Obturatório',
      sub: 'Nervo (Amarelo), Artéria (Vermelho), Veia (Azul)',
      onClick: () => {
        updatePanel(
          '#eab308',
          'FEIXE NOBRE: Nervo, Artéria e Veia',
          'Estruturas nobres emergindo do canal obturatório',
          'Anatomia do Feixe NAV',
          '• Nervo Obturatório: Mais superior e lateral no canal.',
          '• Artéria Obturatória: Intermediária (ramo ilíaco interno).',
          '• Veia Obturatória: Mais inferior e medial.',
          '• Destino: Compartimento medial (adutor) da coxa.',
          'ATENÇÃO EM PROVAS:',
          'A variante Corona Mortis conecta a a. epigástrica à a. obturatória!'
        );
      }
    }
  ];

  hotspots.forEach(hs => {
    if (!hs.el) return;
    hs.el.addEventListener('mouseenter', (e) => showTooltip(hs.title, hs.sub, e));
    hs.el.addEventListener('mousemove', moveTooltip);
    hs.el.addEventListener('mouseleave', hideTooltip);
    hs.el.addEventListener('click', hs.onClick);
    hs.el.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        hs.onClick();
      }
    });
  });

})();
